function subarrayLCM(nums, k) {
  function gcd(a, b) {
    while (b !== 0) {
      const rest = a % b;
      a = b;
      b = rest;
    }
    return a;
  }

  let count = 0;
  for (let start = 0; start < nums.length; start++) {
    let lcm = 1;
    for (let end = start; end < nums.length; end++) {
      lcm = (lcm / gcd(lcm, nums[end])) * nums[end];
      if (k % lcm !== 0) {
        break;
      }
      if (lcm === k) {
        count++;
      }
    }
  }
  return count;
}

