function subarrayLCM(nums, k) {
  // For every subarray, find the smallest m in 1..k that all its elements divide.
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i; j < nums.length; j++) {
      const part = nums.slice(i, j + 1);
      let smallest = -1;
      for (let m = 1; m <= k; m++) {
        if (part.every(v => m % v === 0)) { smallest = m; break; }
      }
      if (smallest === k) total++;
    }
  }
  return total;
}

