function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const k = size === 'large'
    ? pick([360, 420, 720, 840, 960, 1000, 600, 504])
    : pick([1, 2, 6, 12, 18, 20, 24, 30, 36, 7, 1 + Math.floor(rand() * 60)]);
  const divisors = [];
  for (let d = 1; d <= k; d++) if (k % d === 0) divisors.push(d);
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 8);
  const stray = size === 'large' ? 0.02 : 0.25;
  const limit = size === 'large' ? 1000 : 60;
  const nums = Array.from({ length: n }, () => (rand() < stray ? 1 + Math.floor(rand() * limit) : pick(divisors)));
  return [nums, k];
}
